INSERT INTO _migration_505_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_bghl_numbers_s2_001', 'topic_bece_ghlang_numbers', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'What does the Twi numeral “baako” mean?', 'multiple_choice', NULL, '["A. One","B. Two","C. Three","D. Ten"]', 'A', 'Baako means one. Two is mmienu, three is mmiɛnsa and ten is du, so the other options are different numerals. Therefore the correct answer is A: One.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_numbers_s2_002', 'topic_bece_ghlang_numbers', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'A trader sells “du” oranges to a customer. How many oranges did the customer buy?', 'multiple_choice', NULL, '["A. Five","B. Ten","C. Twenty","D. One hundred"]', 'B', 'Du means ten in Twi. Five is enum, twenty is aduonu and one hundred is ɔha, so only ten matches the numeral in the sentence. Therefore the correct answer is B: Ten.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Determine', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_numbers_s2_003', 'topic_bece_ghlang_numbers', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'Which Twi numeral means “two”?', 'multiple_choice', NULL, '["A. Mmiɛnsa","B. Enum","C. Mmienu","D. Nson"]', 'C', 'Mmienu means two. Mmiɛnsa is three, enum is five and nson is seven, so they are all distractors from the basic counting list. Therefore the correct answer is C: Mmienu.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_numbers_s2_004', 'topic_bece_ghlang_numbers', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'The numeral “aduonu” in Twi stands for which number?', 'multiple_choice', NULL, '["A. Twelve","B. Thirty","C. Two hundred","D. Twenty"]', 'D', 'Aduonu is built from adu- (tens) and -nu (two): two lots of ten, which is 2 × 10 = 20. Twelve is dumienu, thirty is aduasa and two hundred is ahaenu, so twenty is the only match. Therefore the correct answer is D: Twenty.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Determine', 'AO2', NULL, NULL, 'board_waec'),
('q_bghl_numbers_s2_005', 'topic_bece_ghlang_numbers', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'How do you say “fifteen” in Twi?', 'multiple_choice', NULL, '["A. Dunum","B. Dunan","C. Aduonum","D. Enum"]', 'A', 'Dunum joins du (ten) and num (five): 10 + 5 = 15. Dunan is fourteen (10 + 4), aduonum is fifty (5 × 10) and enum is simply five, so they do not give fifteen. Therefore the correct answer is A: Dunum.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Determine', 'AO2', NULL, NULL, 'board_waec'),
('q_bghl_numbers_s2_006', 'topic_bece_ghlang_numbers', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'What number is “ɔha” in Akan counting?', 'multiple_choice', NULL, '["A. One thousand","B. One hundred","C. Ten","D. Sixty"]', 'B', 'Ɔha means one hundred. One thousand is apem, ten is du and sixty is aduosia, so those options name other counting milestones. Therefore the correct answer is B: One hundred.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_numbers_s2_007', 'topic_bece_ghlang_numbers', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'The Twi numeral “aduasa” represents which number?', 'multiple_choice', NULL, '["A. Thirteen","B. Three","C. Thirty","D. Three hundred"]', 'C', 'Aduasa is a compound numeral: adu- (tens) plus -sa (three) gives 3 × 10 = 30. Thirteen is dumiɛnsa (10 + 3), three alone is mmiɛnsa and three hundred is ahasa, so only thirty fits. Therefore the correct answer is C: Thirty.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Determine', 'AO3', NULL, NULL, 'board_waec'),
('q_bghl_numbers_s2_008', 'topic_bece_ghlang_numbers', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'How are ordinal numbers such as “second” and “third” formed in Akan?', 'multiple_choice', NULL, '["A. By adding “fo” after the cardinal number","B. By repeating the cardinal number twice","C. By adding “de” before the cardinal number","D. By placing “ɔto so” before the cardinal number, as in “ɔto so mmienu” (second)"]', 'D', 'Akan forms ordinals with the pattern “ɔto so” plus the cardinal number: ɔto so mmienu is second and ɔto so mmiɛnsa is third. “First” is the exception and is expressed with “a ɔdi kan” (the one that leads). Therefore the correct answer is D: By placing “ɔto so” before the cardinal number, as in “ɔto so mmienu” (second).', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_waec');
INSERT INTO _migration_505_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_505_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_505_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'bece-ghlang-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana''s published NaCCA Common Core Programme Ghanaian Language curriculum; not official WAEC or NaCCA examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_505_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'bece-ghlang-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to Ghana''s published NaCCA Common Core Programme Ghanaian Language curriculum; not official WAEC or NaCCA examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/common-core-programme-ccp/', 0, 1 FROM _migration_505_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_505_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_505_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 8 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_505_expected e ON e.id = r.question_id WHERE r.batch_id IS 'bece-ghlang-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana''s published NaCCA Common Core Programme Ghanaian Language curriculum; not official WAEC or NaCCA examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 8 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_505_expected e ON e.id = q.id) = 8 AND (SELECT COUNT(*) FROM questions q JOIN subjects s ON s.id = q.subject_id AND s.exam_type_id = q.exam_type_id JOIN _migration_505_expected e ON e.id = q.id) = 8 THEN 1 ELSE 0 END;
